'use client';

import { useKDSStore } from '../store/kdsStore';
import { useShallow } from 'zustand/react/shallow';
import { ChevronUp, ChevronDown, Menu } from 'lucide-react';

export const KDSFooter: React.FC = () => {
    const { orders } = useKDSStore(useShallow((state) => ({
        orders: Object.values(state.orders),
    })));

    const counts = {
        all: orders.length,
        queue: orders.filter(o => o.stage === 'NEW').length,
        cooking: orders.filter(o => o.stage === 'FIRED').length,
        packing: orders.filter(o => o.stage === 'READY').length,
        delayed: orders.filter(o => o.isDelayed).length,
    };

    return (
        <footer className="h-[56px] bg-white border-t border-gray-200 flex items-center justify-between px-6 shrink-0 z-50">
            {/* LEFT: Branding */}
            <div className="flex items-center gap-4 w-1/4">
                <Menu size={24} className="text-gray-900 cursor-pointer" />
                <div className="flex flex-col">
                    <span className="text-[12px] font-black tracking-tight leading-none text-gray-900">
                        <span className="text-orange-500">kitchen</span>united<span className="text-orange-500">mix</span>
                    </span>
                    <span className="text-[10px] font-bold text-gray-400">Kitchen Location</span>
                </div>
            </div>

            {/* CENTER: Status Filters */}
            <div className="flex items-center h-full gap-8">
                <div className="flex items-center h-full border-b-2 border-black px-1 cursor-pointer">
                    <span className="text-sm font-bold tracking-tight text-black flex items-center gap-1.5 uppercase">
                        View All <span className="opacity-40">{counts.all}</span>
                    </span>
                </div>
                <div className="flex items-center h-full px-1 border-b-2 border-transparent hover:border-gray-200 transition-all cursor-pointer">
                    <span className="text-sm font-bold tracking-tight text-gray-400 flex items-center gap-1.5 uppercase transition-colors">
                        Queue <span className="opacity-40">{counts.queue}</span>
                    </span>
                </div>
                <div className="flex items-center h-full px-1 border-b-2 border-transparent hover:border-gray-200 transition-all cursor-pointer">
                    <span className="text-sm font-bold tracking-tight text-gray-400 flex items-center gap-1.5 uppercase transition-colors">
                        Cooking <span className="opacity-40">{counts.cooking}</span>
                    </span>
                </div>
                <div className="flex items-center h-full px-1 border-b-2 border-transparent hover:border-gray-200 transition-all cursor-pointer">
                    <span className="text-sm font-bold tracking-tight text-gray-400 flex items-center gap-1.5 uppercase transition-colors">
                        Packing <span className="opacity-40">{counts.packing}</span>
                    </span>
                </div>
                <div className="flex items-center h-full px-1 border-b-2 border-transparent hover:border-gray-200 transition-all cursor-pointer">
                    <span className="text-sm font-bold tracking-tight text-gray-400 flex items-center gap-1.5 uppercase transition-colors">
                        Delayed <span className="opacity-40">{counts.delayed}</span>
                    </span>
                </div>
            </div>

            {/* RIGHT: Pagination */}
            <div className="flex items-center justify-end gap-4 w-1/4">
                <div className="flex items-center border border-gray-200 rounded overflow-hidden">
                    <button className="p-2 hover:bg-gray-50 border-r border-gray-200 text-gray-400 transition-colors">
                        <ChevronUp size={16} />
                    </button>
                    <div className="px-3 bg-gray-50 flex items-center">
                        <span className="text-[11px] font-bold text-gray-900">Page 1 of 1</span>
                    </div>
                    <button className="p-2 hover:bg-gray-50 text-gray-400 transition-colors">
                        <ChevronDown size={16} />
                    </button>
                </div>
            </div>
        </footer>
    );
};
